            if(settingsWindowMotion.Value<=0||settingsWindowMotion.Value>=.99)throw new Exception("Quick settings lost the existing entrance motion");quickSettingsButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(settings!=original)throw new Exception("Repeated settings action creates duplicate windows");AdvanceUi(70);
