        static IEnumerable<T> Descendants<T>(DependencyObject root) where T:DependencyObject {if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Descendants<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
        bool Hits(FrameworkElement element){var point=element.TranslatePoint(new Point(element.ActualWidth/2,element.ActualHeight/2),this);var hit=InputHitTest(point) as DependencyObject;while(hit!=null){if(hit==element)return true;hit=hit is Visual?VisualTreeHelper.GetParent(hit):LogicalTreeHelper.GetParent(hit);}return false;}
        void AdvanceUi(int frames){for(int i=0;i<frames;i++)uiMotion.Advance(1.0/60);}
        FluidToggle SettingsToggle(string title){return Descendants<FluidToggle>(settingsPages.Current).First(t=>Convert.ToString(t.ToolTip)==title);}
        Button TimerButton(string title){return Descendants<Button>(timerPage).First(b=>Convert.ToString(b.Content)==title||Convert.ToString(b.ToolTip)==title);}
